export const makeInventoryReservationCreateExecutionService = (dependencies: {
  readonly backend: InventoryReservationCreateBackend;
  readonly effects: ReservationCreateEffectPersistence;
  readonly ledger: InventoryEffectLedgerService;
}): InventoryReservationCreateExecutionService => ({
  execute: Effect.fn('InventoryReservationCreateExecution.execute')(function* execute(scope, request) {
    if (request.authority.tenantId !== scope.tenantId || request.legalEntityId !== scope.legalEntityId) {
      return yield* rejected(request.effectId, 'TENANT_SCOPE_MISMATCH');
    }
    const current = yield* dependencies.effects.read(request.effectId).pipe(
      Effect.flatMap(
        Option.match({
          onNone: () => Effect.fail(unavailable(request.effectId, 'Durable Reservation create intent was not found')),
          onSome: Effect.succeed,
        }),
      ),
    );
    if (canonicalRequest(current.request) !== canonicalRequest(request)) {
      return yield* rejected(request.effectId, 'EFFECT_ID_CONFLICT');
    }
    const ledgerRecord = yield* dependencies.ledger
      .recover(
        request.authority.tenantId,
        inventoryEffectLedgerId(request.effectId),
        reservationCreateLedgerIntent(current),
      )
      .pipe(Effect.mapError((cause) => mapLedgerError(request.effectId, cause)));
    if (
      Schema.is(EstablishedReservationCreateEffectSchema)(current) ||
      Schema.is(ResolvedNoReservationCreateEffectSchema)(current)
    ) {
      yield* synchronizeInventoryEffectLedger(
        dependencies.ledger,
        ledgerRecord.record,
        reservationCreateLedgerResolution(current),
      ).pipe(Effect.mapError((cause) => mapLedgerError(request.effectId, cause)));
      return yield* Effect.void;
    }
    const observation = yield* dependencies.backend.create(current.request);
    const result = yield* applyObservation(dependencies.effects, current, observation);
    yield* synchronizeInventoryEffectLedger(
      dependencies.ledger,
      ledgerRecord.record,
      reservationCreateLedgerResolution(result.effect),
    ).pipe(Effect.mapError((cause) => mapLedgerError(request.effectId, cause)));
    return yield* Effect.void;
  }),
});

export const makeInventoryReservationCreateService = (
  dependencies: Dependencies,
): InventoryReservationCreateService => {
  const planner = makeReservationAllocationPlanner(dependencies);
  return {
    create: Effect.fn('InventoryReservationCreateService.create')(function* createReservation(payload, context) {
      if (
        payload.reservationRef.tenantId !== context.tenantId ||
        context.trustedStorefrontId === undefined ||
        payload.commerceContext.storefrontRef.appId !== context.trustedStorefrontId
      ) {
        return yield* rejected(payload.effectId, 'TENANT_SCOPE_MISMATCH');
      }
      const existing = yield* dependencies.effects.read(payload.effectId);
      if (Option.isSome(existing)) {
        if (!sameReservationCreateIntent(existing.value.request, payload, context)) {
          return yield* rejected(payload.effectId, 'EFFECT_ID_CONFLICT');
        }
        yield* dependencies.ledger
          .claim(
            context.tenantId,
            inventoryEffectLedgerId(payload.effectId),
            reservationCreateLedgerIntent(existing.value),
          )
          .pipe(Effect.mapError((cause) => mapLedgerError(payload.effectId, cause)));
        return { dispatchRequested: false, result: resultForEffect(existing.value) };
      }
      const commerceContext = yield* dependencies.commerceContexts.resolveCurrent({
        customerConfigurationId: payload.customerConfigurationId,
        effectId: payload.effectId,
        legalEntityId: context.legalEntityId,
        storefrontId: context.trustedStorefrontId,
        tenantId: context.tenantId,
      });
      if (
        commerceContext.tenantId !== context.tenantId ||
        commerceContext.sellingLegalEntityRef.resourceId !== context.legalEntityId ||
        commerceContext.storefrontRef.appId !== context.trustedStorefrontId ||
        !sameCommerceContext(commerceContext, payload.commerceContext)
      ) {
        return yield* rejected(payload.effectId, 'COMMERCE_CONTEXT_NOT_ELIGIBLE');
      }
      const trustedPayload = { ...payload, commerceContext };
      const attemptEffect = yield* dependencies.effects.findByAttempt(payload.attemptId);
      if (Option.isSome(attemptEffect)) {
        let reason: InventoryReservationCreateRejected['reason'] = 'ATTEMPT_HAS_UNRESOLVED_EFFECT';
        if (Schema.is(EstablishedReservationCreateEffectSchema)(attemptEffect.value)) {
          reason = 'ATTEMPT_ALREADY_BOUND';
        } else if (Schema.is(ResolvedNoReservationCreateEffectSchema)(attemptEffect.value)) {
          reason = 'ATTEMPT_ALREADY_RESOLVED';
        }
        return yield* rejected(payload.effectId, reason);
      }
      const authority = yield* dependencies.backendConfigurations.findCurrent(payload.customerConfigurationId).pipe(
        Effect.mapError((cause: InventoryBackendConfigurationPersistenceUnavailable) =>
          unavailable(payload.effectId, 'Selected Inventory Backend is unavailable', cause),
        ),
        Effect.flatMap(
          Option.match({
            onNone: () => Effect.fail(rejected(payload.effectId, 'AUTHORITY_NOT_SELECTED')),
            onSome: Effect.succeed,
          }),
        ),
        Effect.flatMap((selected) => requireSupportedAuthority(payload.effectId, selected)),
      );
      const bindingScopes = [
        ...new Map(
          payload.demands.map((demand) => [
            `${context.tenantId}:${demand.exactSelectionMeaning.kind}:${demand.exactSelectionMeaning.id}`,
            { exactSelectionMeaning: demand.exactSelectionMeaning, tenantId: context.tenantId },
          ]),
        ).values(),
      ];
      yield* dependencies
        .lockBindingScopes(bindingScopes)
        .pipe(
          Effect.mapError((cause) =>
            unavailable(payload.effectId, 'Catalog-to-Stock Binding evidence is unavailable', cause),
          ),
        );
      const demands = yield* Effect.forEach(
        payload.demands,
        (demand) =>
          dependencies.resolver.resolve(demand).pipe(
            Effect.catchTag('CatalogToStockBindingRejected', failCatalogToStockBindingResolution),
            Effect.mapError((cause) =>
              Schema.is(CatalogToStockBindingUnavailable)(cause)
                ? unavailable(payload.effectId, 'Catalog-to-Stock Binding evidence is unavailable', cause)
                : cause,
            ),
          ),
        { concurrency: 1 },
      );
      let replayAfterContention: ReservationCreateEffect | undefined;
      const requirements = yield* planner.plan(payload.effectId, authority, demands, commerceContext, () =>
        dependencies.effects.read(payload.effectId).pipe(
          Effect.flatMap(
            Option.match({
              onNone: () => Effect.succeed(false),
              onSome: (contendingEffect) => {
                if (!sameReservationCreateIntent(contendingEffect.request, payload, context)) {
                  return Effect.fail(rejected(payload.effectId, 'EFFECT_ID_CONFLICT'));
                }
                replayAfterContention = contendingEffect;
                return Effect.succeed(true);
              },
            }),
          ),
        ),
      );
      if (replayAfterContention !== undefined) {
        return { dispatchRequested: false, result: resultForEffect(replayAfterContention) };
      }
      const legalEntityId = yield* Schema.decodeEffect(LegalEntityIdSchema)(context.legalEntityId).pipe(
        Effect.mapError((cause) => unavailable(payload.effectId, 'Legal Entity scope is invalid', cause)),
      );
      const sourceActionInvocationId = yield* Schema.decodeEffect(ActionInvocationIdSchema)(
        context.actionInvocationId,
      ).pipe(Effect.mapError((cause) => unavailable(payload.effectId, 'Action identity is invalid', cause)));
      const request: InventoryReservationCreateRequest = {
        authority,
        commerceContext,
        effectId: payload.effectId,
        legalEntityId,
        mutationId: dependencies.makeMutationId(),
        requestedAt: DateTime.formatIso(yield* DateTime.now),
        reservation: {
          origin: { attemptId: payload.attemptId, kind: 'ORDER_COMMITMENT_ATTEMPT' },
          ref: payload.reservationRef,
          requirements,
        },
        sourceActionInvocationId,
      };
      yield* dependencies.ledger
        .claim(
          context.tenantId,
          inventoryEffectLedgerId(request.effectId),
          reservationCreateLedgerIntent({ _tag: 'REQUESTED', request }),
        )
        .pipe(Effect.mapError((cause) => mapLedgerError(request.effectId, cause)));
      const stored = yield* dependencies.effects.createOrRead(request);
      if (!sameReservationCreateIntent(stored.effect.request, trustedPayload, context)) {
        return yield* rejected(payload.effectId, 'EFFECT_ID_CONFLICT');
      }
      return { dispatchRequested: stored.outcome === 'INSERTED', result: resultForEffect(stored.effect) };
    }),
  };
};
